5.4 Task 3.3: Create New Columns with Mutate
Create new variables based on existing ones:

# Create a cost_per_day column
practice_data |&gt;
  mutate(cost_per_day = ___ / ___) |&gt;
  select(patient_id, total_charges, los, cost_per_day)


# Create age groups
practice_data |&gt;
  mutate(
    age_group = case_when(
      age &lt; ___ ~ "Under 40",
      age &lt; ___ ~ "40-64",
      TRUE ~ "65+"
    )
  ) |&gt;
  select(patient_id, age, age_group)


# Flag high-cost patients (total charges &gt; $25,000)
practice_data |&gt;
  mutate(high_cost = ___ &gt; ___) |&gt;
  select(patient_id, total_charges, high_cost)

5.5 Task 3.4: Sort with Arrange
Order your data:

# Sort by age (youngest first)
practice_data |&gt;
  arrange(___) |&gt;
  select(patient_id, age, department)


# Sort by total charges (highest first)
# Hint: use desc() for descending order
practice_data |&gt;
  arrange(desc(___)) |&gt;
  select(patient_id, total_charges)


# Sort by department, then by age within each department
practice_data |&gt;
  arrange(___, ___) |&gt;
  select(patient_id, department, age)
